        Object parsed = this.parseOHLCV(message, market);
        Helpers.callDynamically(stored, "append", new Object[]{parsed});
        Object messageHash = Helpers.add(Helpers.add(Helpers.add("ohlcv:", timeframe), ":"), symbol);
